if(typeof $json.pauta_id!=='string'||!$json.pauta_id.trim()||!Array.isArray($json.findings)||!$json.findings.length||$json.findings.length>30)throw Error('Parecer de pauta inválido.');
// A consulta existente exige um identificador numérico. Cada chamada recebe só uma pauta.
return {json:{post_id:1,findings:$json.findings}};

const input=$('Receber parecer da pauta').first().json;
const results=$input.all().map(({json})=>json).filter(x=>Number.isInteger(x.claim_index));
const googleFactCheck=results.map(({claim_index,status,http_status,candidates})=>({claim_index,status,http_status,candidates}));
const findings=input.findings.map(({claim,sourceId,quote})=>({claim,status:'pendente',action:sourceId&&quote?'atribuir_ou_omitir':'omitir_ou_apurar',editorEvidence:sourceId&&quote?{sourceId,quote}:null}));
return [{json:{...input,decision:'devolver_para_ajuste',reason:'A consulta complementar fornece candidatos. A revisão deve preservar a atribuição e omitir alegações sensíveis sem evidência suficiente.',findings,googleFactCheck,modelCalls:0}}];
